// The secrets of the web version (API keys, pairing codes), encrypted in the browser with Web Crypto.
//
// Three ways to keep them, chosen in the settings:
// - "device"     : encrypted (AES-GCM 256) with a key generated by the browser that cannot be exported;
//                  the vault opens by itself on this browser profile. Default.
// - "passphrase" : encrypted with a key derived from a passphrase (PBKDF2-SHA-256, 600 000 rounds), asked once
//                  per visit; the derived key lives only in memory.
// - "session"    : nothing is written; the secrets are forgotten when the tab is closed or reloaded.
// A secret leaves the browser only towards the service it opens (see backend.js); it is never shown again.
(function (root, factory) {
  const api = factory(root);
  if (typeof module === "object" && module.exports) module.exports = api;
  root.KenobiVault = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function (root) {
  "use strict";

  const Store = typeof module === "object" && module.exports ? require("./store.js") : root.KenobiStore;
  const RECORD = "vault";
  const DEVICE_KEY = "vault-device-key";
  const PREFERENCE = "vault-mode"; // "session" is remembered (never the keys), so a reload does not start saving them
  const ITERATIONS = 600000;
  const MODES = ["device", "passphrase", "session"];

  class VaultLocked extends Error {
    constructor() {
      super("Clés verrouillées : déverrouille-les avec ta phrase secrète.");
      this.name = "VaultLocked";
      this.status = 423;
    }
  }

  let cache = null;        // decrypted secrets {name: value}, in memory only
  let sessionOnly = null;  // secrets of the "session" mode
  let passphraseKey = null;
  let loaded = false;
  let record = null;       // what is stored: {v, mode, salt, iv, data}

  const subtle = () => root.crypto && root.crypto.subtle;
  const bytes = (text) => new TextEncoder().encode(text);
  const toBase64 = (buffer) => {
    let binary = "";
    for (const byte of new Uint8Array(buffer)) binary += String.fromCharCode(byte);
    return root.btoa(binary);
  };
  const fromBase64 = (text) => Uint8Array.from(root.atob(text), (character) => character.charCodeAt(0));

  async function deviceKey() {
    let key = await Store.get(DEVICE_KEY);
    if (!key) {
      key = await subtle().generateKey({ name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
      await Store.set(DEVICE_KEY, key);
    }
    return key;
  }

  async function deriveKey(passphrase, salt) {
    const material = await subtle().importKey("raw", bytes(passphrase), "PBKDF2", false, ["deriveKey"]);
    return subtle().deriveKey({ name: "PBKDF2", salt, iterations: ITERATIONS, hash: "SHA-256" }, material,
      { name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
  }

  async function encrypt(key, secrets) {
    const iv = root.crypto.getRandomValues(new Uint8Array(12));
    const data = await subtle().encrypt({ name: "AES-GCM", iv }, key, bytes(JSON.stringify(secrets)));
    return { iv: toBase64(iv), data: toBase64(data) };
  }

  async function decrypt(key, stored) {
    const plain = await subtle().decrypt({ name: "AES-GCM", iv: fromBase64(stored.iv) }, key, fromBase64(stored.data));
    const value = JSON.parse(new TextDecoder().decode(plain));
    return value && typeof value === "object" ? value : {};
  }

  async function load() {
    if (loaded) return;
    record = (await Store.get(RECORD)) || null;
    loaded = true;
    if (!record) {
      if ((await Store.get(PREFERENCE)) === "session") sessionOnly = {};
      return;
    }
    if (record.mode === "device") {
      try {
        cache = await decrypt(await deviceKey(), record);
      } catch {
        cache = {}; // the browser lost its key: the secrets cannot be read again
      }
    }
  }

  function mode() {
    if (sessionOnly) return "session";
    return record?.mode || "device";
  }

  async function status() {
    await load();
    const current = mode();
    return {
      mode: current,
      locked: current === "passphrase" && !cache,
      available: Boolean(subtle()),
      persistent: Boolean(Store.available && Store.available())
    };
  }

  async function secrets() {
    await load();
    if (sessionOnly) return sessionOnly;
    if (record?.mode === "passphrase" && !cache) throw new VaultLocked();
    return cache || {};
  }

  async function save(next) {
    if (sessionOnly) {
      sessionOnly = next;
      return;
    }
    if (!subtle()) throw new Error("Ce navigateur ne sait pas chiffrer (Web Crypto) : choisis « pour cette visite seulement ».");
    const current = record?.mode === "passphrase" ? "passphrase" : "device";
    const key = current === "passphrase" ? passphraseKey : await deviceKey();
    if (!key) throw new VaultLocked();
    const sealed = await encrypt(key, next);
    // The names (never the values) stay readable, so a locked vault can still say which keys exist.
    record = { v: 1, mode: current, ...(current === "passphrase" ? { salt: record.salt } : {}), names: Object.keys(next), ...sealed };
    await Store.set(RECORD, record);
    cache = next;
  }

  async function get(name) {
    const all = await secrets();
    return typeof all[name] === "string" ? all[name] : "";
  }

  async function has(name) {
    try {
      return Boolean(await get(name));
    } catch (error) {
      if (error instanceof VaultLocked) return Boolean(record?.names?.includes?.(name));
      throw error;
    }
  }

  async function set(name, value) {
    const next = { ...(await secrets()) };
    if (value) next[name] = String(value);
    else delete next[name];
    await save(next);
  }

  async function unlock(passphrase) {
    await load();
    if (record?.mode !== "passphrase") return true;
    try {
      const key = await deriveKey(String(passphrase || ""), fromBase64(record.salt));
      cache = await decrypt(key, record);
      passphraseKey = key;
      return true;
    } catch {
      return false;
    }
  }

  function lock() {
    if (record?.mode === "passphrase") {
      cache = null;
      passphraseKey = null;
    }
  }

  // Changes how the secrets are kept; they follow (re-encrypted, or kept in memory only).
  async function setMode(next, passphrase) {
    if (!MODES.includes(next)) throw new Error("Mode inconnu.");
    const current = { ...(await secrets()) };
    if (next === "session") {
      sessionOnly = current;
      record = null;
      cache = null;
      passphraseKey = null;
      await Store.remove(RECORD);
      await Store.set(PREFERENCE, "session");
      return status();
    }
    sessionOnly = null;
    await Store.remove(PREFERENCE);
    if (next === "passphrase") {
      if (String(passphrase || "").length < 8) throw new Error("Phrase secrète trop courte : 8 caractères au moins.");
      const salt = root.crypto.getRandomValues(new Uint8Array(16));
      passphraseKey = await deriveKey(String(passphrase), salt);
      record = { v: 1, mode: "passphrase", salt: toBase64(salt) };
    } else {
      passphraseKey = null;
      record = { v: 1, mode: "device" };
    }
    await save(current);
    return status();
  }

  async function clearAll() {
    sessionOnly = sessionOnly ? {} : null;
    cache = {};
    passphraseKey = null;
    record = null;
    await Store.remove(RECORD);
    await Store.remove(DEVICE_KEY);
  }

  return { VaultLocked, status, get, has, set, unlock, lock, setMode, clearAll, MODES };
});
